// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/terminal/PasteShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Paste images: the terminal's right-click menu open over a Claude Code
 * session, ported from the app's ContextMenu (src/ui/ContextMenu.tsx) with
 * the actions a terminal registers (src/terminal/Terminal.tsx) and the
 * AsyncButton rows they render as (src/ui/AsyncButton.tsx). Nothing is
 * selected, so Copy text and Clear selection are disabled, as in the app.
 * Picking an action, a press outside the menu or Escape closes it; a
 * right-click on the terminal opens it again where the pointer is.
 */
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { ClipboardPaste, Copy, Eraser, TextSelect, type LucideIcon } from "lucide-react";
import { AnsiScreen } from "../../home/ansi";
import { CaptureTile, Viewport } from "./parts";
import { TILE_BOX, TileShot } from "./frames";

const ACTIONS: { label: string; icon: LucideIcon; disabled: boolean }[] = [
  { label: "Copy text", icon: Copy, disabled: true },
  { label: "Paste text or image", icon: ClipboardPaste, disabled: false },
  { label: "Select all", icon: TextSelect, disabled: false },
  { label: "Clear selection", icon: Eraser, disabled: true },
];

// Where the scene's menu was opened: a right-click on the session's answer,
// in window coordinates.
const OPENED_AT = { x: 132, y: 296 };

export function PasteShot() {
  const [menu, setMenu] = useState<{ x: number; y: number } | null>(OPENED_AT);
  const menuRef = useRef<HTMLDivElement>(null);
  const viewport = useRef<HTMLDivElement>(null);
  const host = useRef<HTMLSpanElement>(null);

  // A right-click on the terminal opens the menu at the pointer, like the app.
  useEffect(() => {
    const term = host.current?.parentElement;
    if (!term) return;
    const open = (event: MouseEvent) => {
      const box = viewport.current;
      if (!box) return;
      event.preventDefault();
      const rect = box.getBoundingClientRect();
      const scale = rect.width / box.offsetWidth || 1;
      setMenu({ x: (event.clientX - rect.left) / scale, y: (event.clientY - rect.top) / scale });
    };
    term.addEventListener("contextmenu", open);
    return () => term.removeEventListener("contextmenu", open);
  }, []);

  // The app's placement: at the pointer, kept 8px inside the viewport.
  useLayoutEffect(() => {
    const element = menuRef.current;
    if (!menu || !element) return;
    element.style.left = `${Math.max(8, Math.min(menu.x, TILE_BOX.width - element.offsetWidth - 8))}px`;
    element.style.top = `${Math.max(8, Math.min(menu.y, TILE_BOX.height - element.offsetHeight - 8))}px`;
  }, [menu]);

  const close = () => setMenu(null);
  return (
    <TileShot
      backdrop="chat"
      session="web"
      tile={
        <CaptureTile key="web" id="web" kbd="⌘1">
          <AnsiScreen id="web-86" />
          <span ref={host} hidden />
        </CaptureTile>
      }
      overlay={
        <Viewport width={TILE_BOX.width} height={TILE_BOX.height} z={6000} passThrough={!menu} viewportRef={viewport}>
          {menu ? (
            <div className="app-context-backdrop pzza-portal" onMouseDown={close}>
              <div
                ref={menuRef}
                className="menu app-context-menu"
                role="menu"
                aria-label="Context actions"
                tabIndex={-1}
                onMouseDown={(event) => {
                  event.preventDefault();
                  event.stopPropagation();
                }}
                onKeyDown={(event) => {
                  event.stopPropagation();
                  if (event.key === "Escape" || event.key === "Tab") {
                    event.preventDefault();
                    close();
                  }
                }}
              >
                {ACTIONS.map(({ label, icon: Icon, disabled }) => (
                  <button key={label} type="button" className="menu-item async-button" role="menuitem" disabled={disabled} aria-busy={false} onClick={close}>
                    <span className="async-button-icon" style={{ width: 16, height: 16 }} aria-hidden="true">
                      <Icon size={16} strokeWidth={2} />
                    </span>
                    {label}
                  </button>
                ))}
              </div>
            </div>
          ) : null}
        </Viewport>
      }
    />
  );
}
